// rsync-lite — rolling-hash file synchronization
// Block size: 4 KiB, Hash: sha256

const BLOCK_SIZE = 4 * 1024;

fn block_hashes::(data) {
    let out = [];
    let total = @len(data);
    let mut off = 0;
    while (off < total) {
        let n = @min(BLOCK_SIZE, total - off);
        let slice = @str_slice_utf8(data, off, n);
        @push(out, {"offset": off, "size": n, "hash": @sha256_hex(@bytes(slice))});
        off += n;
    }
    return out;
}

fn compute_delta::(source, target_hashes) {
    let source_set = {};
    for b in block_hashes(source) { source_set[b["hash"]] = b; }
    let delta = [];
    for tb in target_hashes {
        if (@map_has_key(source_set, tb["hash"])) {
            @push(delta, {"op": "copy", "from": source_set[tb["hash"]]["offset"],
                           "size": tb["size"]});
        } else {
            @push(delta, {"op": "insert", "target_offset": tb["offset"],
                           "size": tb["size"]});
        }
    }
    return delta;
}

fn apply_delta::(source, target, delta) {
    let out = "";
    for op in delta {
        if (op["op"] == "copy") { out += @str_slice_utf8(source, op["from"], op["size"]); }
        else { out += @str_slice_utf8(target, op["target_offset"], op["size"]); }
    }
    return out;
}

fn transfer_ratio::(delta) {
    let inserted = 0;
    let copied = 0;
    for op in delta {
        if (op["op"] == "insert") { inserted += op["size"]; }
        else { copied += op["size"]; }
    }
    return inserted / (inserted + copied);
}

fn version::() { return "1.0.0"; }
